struct Box { item: Cell, extra: Any }
impl Box { fn get(self) -> Cell { return self.item; } }
trait Reader { fn read(self) -> Cell; }
impl Reader for Box { fn read(self) -> Cell { return self.item; } }
enum Choice { Empty, Tuple(item: Cell), Record { item: Cell } }
fn valid(boxed: Box, cell: Cell, reader: Reader) {
 boxed.item.value = 1; boxed.get(); reader.read();
 Box { item: cell, extra: 1 };
 Choice::Empty; Choice::Tuple(cell); Choice::Tuple(item = cell); Choice::Record { item: cell };
}
fn shorthand(item: Cell) { Box { item, extra: 1 }; }

